<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php'; require_once __DIR__.'/admin-ui.php'; require_once __DIR__.'/blog-lib.php';
$user=require_admin();$db=blog_db();$can=admin_can($user,'categories');$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_capability($user,'categories');verify_csrf($_POST['csrf']??null);$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id&&in_array($action,['deactivate','restore'],true)){$status=$action==='restore'?'active':'inactive';$db->prepare('UPDATE categories SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$status,$id]);audit($db,$user,$action==='restore'?'restore':'deactivate','category',$id,['status'=>$status]);$message=$action==='restore'?'Category restored.':'Category deactivated. Existing posts are unchanged.';}}
$items=$db->query('SELECT c.*,COUNT(p.id) post_count FROM categories c LEFT JOIN posts p ON p.category_id=c.id GROUP BY c.id ORDER BY c.status,c.name')->fetchAll(); admin_layout_start('Categories','categories',$user);
?><div class="bar"><div><h1>Categories</h1><p>Organize content without breaking existing posts.</p></div><?php if($can):?><a class="btn" href="/admin/category-edit.php">Add category</a><?php endif?></div><?php if($message):?><p class="notice"><?=htmlspecialchars($message)?></p><?php endif?><section class="card"><table><thead><tr><th>Name</th><th>Slug</th><th>Status</th><th>Meta title</th><th>Posts</th><th>Created</th><th>Updated</th><th>Action</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=htmlspecialchars($i['name'])?></td><td><?=htmlspecialchars($i['slug'])?></td><td><?=htmlspecialchars($i['status'])?></td><td><?=htmlspecialchars($i['meta_title']?:'—')?></td><td><?=$i['post_count']?></td><td><?=htmlspecialchars($i['created_at'])?></td><td><?=htmlspecialchars($i['updated_at'])?></td><td><?php if($can):?><a href="/admin/category-edit.php?id=<?=$i['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$i['id']?>"><input type="hidden" name="action" value="<?=$i['status']==='active'?'deactivate':'restore'?>"><button class="btn alt" onclick="return confirm('<?= $i['status']==='active'?'Deactivate this category? Existing posts keep it.':'Restore this category?'?>')"><?=$i['status']==='active'?'Deactivate':'Restore'?></button></form><?php else:?>View only<?php endif?></td></tr><?php endforeach;if(!$items):?><tr><td colspan="8">No categories yet.</td></tr><?php endif?></tbody></table></section><?php admin_layout_end();
